B.a3V=s([B.ahC],t.nN)
B.ahH=new A.hR("1.4.4","2026-11-09","Hitrej\u0161e brisanje letal in letali\u0161\u010d za urednike.",B.a3V)
B.a2G=s(["Ob registraciji vpi\u0161e\u0161 ime in priimek; obstoje\u010di ra\u010duni ju dodajo v Nastavitve \u2192 Ra\u010dun.","\u010ce naslov \u017ee ima ra\u010dun, aplikacija ponudi prijavo ali spremembo gesla.","V nastavitvah lahko spremeni\u0161 geslo in znova po\u0161lje\u0161 e-po\u0161to za potrditev naslova.","Popravek: shranjevanje napredka ne bri\u0161e ve\u010d drugih podatkov ra\u010duna."],t.s)
B.aho=new A.eq("Ra\u010dun",B.a2G)
B.a1_=s([B.aho],t.nN)
B.ahI=new A.hR("1.4.3","2026-11-09","Ime in priimek ob registraciji, sprememba gesla in potrditev naslova v nastavitvah.",B.a1_)
B.a1i=s(["Letala in letali\u0161\u010da se nalo\u017eijo iz oblaka; brez povezave ostane zadnja prenesena vsebina.","Uredniki v aplikaciji dodajajo, urejajo in bri\u0161ejo letala in letali\u0161\u010da, tudi dodatna polja z lastnimi oznakami.","Spremembe gredo najprej v osnutek, ki ga vidi samo urednik; z gumbom Objavi so vidne vsem."],t.s)
B.ahp=new A.eq("Eksploatacija",B.a1i)
B.a1j=s(["Popravek: tip letala, ki ga v nastavitvah skrije\u0161, obdr\u017ei registracije; ko ga znova poka\u017ee\u0161, so spet na voljo."],t.s)
